//! The `Syscalls` trait with one async method per syscall, the request enum, the `Layered` adapter,
//! user-memory reference types, result and restart types, and the return-to-guest interface.
//!
//! Everything above the kernel talks to it only through this crate. The trait, the request enum
//! and the adapter are generated by `wasixv2-codegen` from `lib/wasixv2/codegen/wit`; see the
//! header of `src/generated.rs`.

mod caller;
mod control;
mod generated;
mod memory;
mod result;

pub use caller::{Caller, TaskId};
pub use control::{
    AtomicWait, AtomicWord, BINPRM_BUF_SIZE, Binfmt, Control, ExecImage, ExitMm, GuestAction,
    Image, ImageId, SignalFrame, VforkParent, WorkFlag,
};
pub use generated::{Layer, Layered, Syscall, SyscallRet, Syscalls, dispatch};
pub use memory::{
    CstrError, Fault, LocalFuture, UserMemory, UserSlice, UserSliceMut, WASM_PAGE_SIZE, copied,
    read_cstr, read_value, write_value,
};
pub use result::{SysErr, SysResult};
pub use wasixv2_abi::{Errno, Fd};
